package pk.edu.dsu.scd.lab04;public final class InventoryService{private int stock;public InventoryService(int s){if(s<0)throw new IllegalArgumentException();stock=s;}public void reserve(int q){if(q<=0)throw new InvalidOrderException("Quantity must be positive");if(q>stock)throw new InsufficientStockException("Insufficient stock");stock-=q;assert stock>=0;}public int getStock(){return stock;}}